package cache

import (
	"time"
)

// Codec описывает абстрактный, строго типизированный (Generic) контракт для кодирования и декодирования кэш-пакетов.
//
// Выступает в роли изолированного маршалера, который переводит доменные сущности V в бинарный payload
// для сохранения в распределенных хранилищах (Redis, KeyDB, Memcached) и восстанавливает их обратно.
type Codec[V any] interface {
	// Marshal сериализует высокоуровневый объект v типа V в сырой массив байт,
	// интегрируя метаданные времени жизни (ttl) непосредственно в итоговый бинарный конверт.
	Marshal(v V, ttl time.Duration) ([]byte, error)

	// Unmarshal принимает сырой массив байт из кэш-хранилища и восстанавливает
	// структурированный конверт Envelope[V], содержащий как целевой объект, так и его рантайм-метрики.
	Unmarshal(b []byte) (*Envelope[V], error)
}
